import React, { useState, useEffect } from "react";
import { Plus, Edit2, Trash2, Map, ShieldAlert, X, ClipboardList } from "lucide-react";
import { collection, onSnapshot, addDoc, updateDoc, deleteDoc, doc, query, where, getDocs, getDoc } from "firebase/firestore";
import { db } from "../firebase";
import { CATALOGO_EVENTOS_POTRERO, TIPOS_EVENTO_POTRERO } from "../catalogoEventos";

const inputStyle = { width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #d1d5db", boxSizing: "border-box" };
const labelStyle = { display: "block", fontSize: "12px", fontWeight: "bold", marginBottom: "4px", color: "#4b5563" };

export default function ConfiguracionPotreros({ usuario }) {
  const [potreros, setPotreros] = useState([]);
  const [formActivo, setFormActivo] = useState(false);
  const [editandoId, setEditandoId] = useState(null);
  const [datosForm, setDatosForm] = useState({
    nombre: "", hectareas: "", tipoPastoNombre: "", porcentajePasto: "",
    tipoPastoTamano: "", numeroPresas: "", numeroBebederos: "", divisiones: []
  });
  const [nuevaDivision, setNuevaDivision] = useState("");

  const [grupos, setGrupos] = useState([]);
  const [formGrupoActivo, setFormGrupoActivo] = useState(false);
  const [editandoGrupoId, setEditandoGrupoId] = useState(null);
  const [datosFormGrupo, setDatosFormGrupo] = useState({ nombre: "" });

  // Estado modal tratamiento potrero
  const [modalTratamiento, setModalTratamiento] = useState(false);
  const [potreroActivo, setPotreroActivo] = useState(null);
  const [datosTratamiento, setDatosTratamiento] = useState({
    tipo: "Desparasitante", resultado: "", fecha: new Date().toISOString().split("T")[0]
  });
  const [guardandoTrat, setGuardandoTrat] = useState(false);
  const [exitoTrat, setExitoTrat] = useState("");

  // Historial modal
  const [modalHistorial, setModalHistorial] = useState(false);
  const [historialPotrero, setHistorialPotrero] = useState([]);
  const [cargandoHistorial, setCargandoHistorial] = useState(false);

  // Tratamiento Masivo (Rancho)
  const [modalTratamientoRancho, setModalTratamientoRancho] = useState(false);
  const [datosTratamientoRancho, setDatosTratamientoRancho] = useState({
    potreroId: "Todos", tipo: "Herbicida", resultado: "", fecha: new Date().toISOString().split("T")[0]
  });
  const [crearRecordatorio, setCrearRecordatorio] = useState(false);
  const [fechaRecordatorio, setFechaRecordatorio] = useState("");
  const [guardandoTratRancho, setGuardandoTratRancho] = useState(false);
  const [exitoTratRancho, setExitoTratRancho] = useState("");

  // Traslado de Ganado
  const [modalTraslado, setModalTraslado] = useState(false);
  const [datosTraslado, setDatosTraslado] = useState({ tipo: "", nombreOrigen: "", potreroDestino: "", grupoDestino: "" });
  const [guardandoTraslado, setGuardandoTraslado] = useState(false);
  const [exitoTraslado, setExitoTraslado] = useState("");

  // UPPs y Perfil del Rancho
  const [ranchoDoc, setRanchoDoc] = useState(null);
  const [nuevaUpp, setNuevaUpp] = useState("");
  const [guardandoUpp, setGuardandoUpp] = useState(false);
  const [guardandoPerfil, setGuardandoPerfil] = useState(false);

  useEffect(() => {
    if (!usuario?.ranchoId) return;
    const unsubP = onSnapshot(query(collection(db, "potreros"), where("ranchoId", "==", usuario.ranchoId)), (snap) => {
      setPotreros(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubG = onSnapshot(query(collection(db, "grupos"), where("ranchoId", "==", usuario.ranchoId)), (snap) => {
      setGrupos(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    
    // Obtener datos del rancho (para UPPs)
    const unsubR = onSnapshot(doc(db, "ranchos", usuario.ranchoId), (docSnap) => {
      if (docSnap.exists()) {
        setRanchoDoc({ id: docSnap.id, ...docSnap.data() });
      }
    });

    return () => { unsubP(); unsubG(); unsubR(); };
  }, [usuario]);

  // ─── Perfil del Rancho ───────────────────────────────────────────────────────
  
  const guardarPerfilRancho = async (campo, valor) => {
    if (!ranchoDoc) return;
    setGuardandoPerfil(true);
    try {
      await updateDoc(doc(db, "ranchos", usuario.ranchoId), {
        [campo]: valor
      });
    } catch (error) {
      console.error("Error actualizando perfil del rancho:", error);
    }
    setGuardandoPerfil(false);
  };

  // ─── UPPs ────────────────────────────────────────────────────────────────────
  
  const agregarUpp = async () => {
    const val = nuevaUpp.trim();
    if (!val || !ranchoDoc) return;
    setGuardandoUpp(true);
    try {
      const currentUpps = ranchoDoc.upps || [];
      if (!currentUpps.includes(val)) {
        await updateDoc(doc(db, "ranchos", usuario.ranchoId), {
          upps: [...currentUpps, val]
        });
      }
      setNuevaUpp("");
    } catch (error) {
      console.error("Error agregando UPP:", error);
    }
    setGuardandoUpp(false);
  };

  const quitarUpp = async (uppIndex) => {
    if (!window.confirm("¿Seguro que deseas eliminar esta UPP?")) return;
    try {
      const newUpps = (ranchoDoc.upps || []).filter((_, idx) => idx !== uppIndex);
      await updateDoc(doc(db, "ranchos", usuario.ranchoId), { upps: newUpps });
    } catch (error) {
      console.error("Error quitando UPP:", error);
    }
  };

  // ─── Divisiones ──────────────────────────────────────────────────────────────

  const agregarDivision = () => {
    const val = nuevaDivision.trim();
    if (!val) return;
    setDatosForm(f => ({ ...f, divisiones: [...f.divisiones, val] }));
    setNuevaDivision("");
  };

  const quitarDivision = (idx) => {
    setDatosForm(f => ({ ...f, divisiones: f.divisiones.filter((_, i) => i !== idx) }));
  };

  // ─── Potreros ────────────────────────────────────────────────────────────────

  const guardarPotrero = async (e) => {
    e.preventDefault();
    try {
      const potreroData = {
        nombre: datosForm.nombre,
        hectareas: Number(datosForm.hectareas) || 0,
        tipoPastoNombre: datosForm.tipoPastoNombre || "",
        porcentajePasto: Number(datosForm.porcentajePasto) || 0,
        tipoPastoTamano: datosForm.tipoPastoTamano || "",
        numeroPresas: Number(datosForm.numeroPresas) || 0,
        numeroBebederos: Number(datosForm.numeroBebederos) || 0,
        divisiones: datosForm.divisiones || [],
        ranchoId: usuario?.ranchoId || null
      };
      if (editandoId) {
        await updateDoc(doc(db, "potreros", editandoId), potreroData);
      } else {
        await addDoc(collection(db, "potreros"), potreroData);
      }
      cerrarFormPotrero();
    } catch (error) { console.error("Error guardando potrero:", error); }
  };

  const cerrarFormPotrero = () => {
    setFormActivo(false);
    setEditandoId(null);
    setNuevaDivision("");
    setDatosForm({ nombre: "", hectareas: "", tipoPastoNombre: "", porcentajePasto: "", tipoPastoTamano: "", numeroPresas: "", numeroBebederos: "", divisiones: [] });
  };

  const editarPotrero = (pot) => {
    setDatosForm({
      nombre: pot.nombre || "",
      hectareas: pot.hectareas || "",
      tipoPastoNombre: pot.tipoPastoNombre || "",
      porcentajePasto: pot.porcentajePasto || "",
      tipoPastoTamano: pot.tipoPastoTamano || "",
      numeroPresas: pot.numeroPresas || "",
      numeroBebederos: pot.numeroBebederos || "",
      divisiones: pot.divisiones || [],
    });
    setEditandoId(pot.id);
    setFormActivo(true);
  };

  const borrarPotrero = async (id) => {
    if (window.confirm("¿Seguro que deseas eliminar este potrero?")) {
      try { await deleteDoc(doc(db, "potreros", id)); }
      catch (error) { console.error("Error borrando potrero:", error); }
    }
  };

  // ─── Tratamiento de potrero ───────────────────────────────────────────────────

  const abrirModalTratamiento = (pot) => {
    setPotreroActivo(pot);
    setDatosTratamiento({ tipo: "Desparasitante", resultado: "", fecha: new Date().toISOString().split("T")[0], costo: "" });
    setExitoTrat("");
    setModalTratamiento(true);
  };

  const guardarTratamientoPotrero = async (e) => {
    e.preventDefault();
    setGuardandoTrat(true);
    try {
      await addDoc(collection(db, "eventosPotreros"), {
        potreroId: potreroActivo.id,
        potreroNombre: potreroActivo.nombre,
        tipo: datosTratamiento.tipo,
        resultado: datosTratamiento.resultado,
        fecha: datosTratamiento.fecha,
        ranchoId: usuario?.ranchoId || null
      });
      setExitoTrat(`✅ Tratamiento registrado en ${potreroActivo.nombre}`);
      setDatosTratamiento({ tipo: "Desparasitante", resultado: "", fecha: new Date().toISOString().split("T")[0] });
      setTimeout(() => { setExitoTrat(""); setModalTratamiento(false); }, 2000);
    } catch (err) { console.error(err); }
    setGuardandoTrat(false);
  };

  const abrirHistorial = async (pot) => {
    setPotreroActivo(pot);
    setCargandoHistorial(true);
    setModalHistorial(true);
    try {
      const q = query(collection(db, "eventosPotreros"), where("potreroId", "==", pot.id));
      const unsubH = onSnapshot(q, (snap) => {
        const lista = snap.docs.map(d => ({ id: d.id, ...d.data() }))
          .sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
        setHistorialPotrero(lista);
        setCargandoHistorial(false);
      });
      return unsubH;
    } catch (err) { console.error(err); setCargandoHistorial(false); }
  };

  const guardarTratamientoRancho = async (e) => {
    e.preventDefault();
    setGuardandoTratRancho(true);
    try {
      const potrerosAfectados = datosTratamientoRancho.potreroId === "Todos" 
        ? potreros 
        : potreros.filter(p => p.id === datosTratamientoRancho.potreroId);

      if (potrerosAfectados.length === 0) {
        alert("No hay potreros registrados.");
        setGuardandoTratRancho(false);
        return;
      }

      for (const pot of potrerosAfectados) {
        await addDoc(collection(db, "eventosPotreros"), {
          potreroId: pot.id,
          potreroNombre: pot.nombre,
          tipo: datosTratamientoRancho.tipo,
          resultado: datosTratamientoRancho.resultado,
          fecha: datosTratamientoRancho.fecha,
          ranchoId: usuario?.ranchoId || null
        });
      }

      if (crearRecordatorio && fechaRecordatorio) {
        const partePotrero = datosTratamientoRancho.potreroId !== "Todos" 
            ? `Potrero: ${potreros.find(p => p.id === datosTratamientoRancho.potreroId)?.nombre || "Desconocido"}` 
            : "Todos los potreros";
        const tituloRecord = `${datosTratamientoRancho.tipo}${datosTratamientoRancho.resultado ? ` (${datosTratamientoRancho.resultado})` : ""} — ${partePotrero}`;
        await addDoc(collection(db, "alertas"), {
          fechaProgramada: fechaRecordatorio,
          titulo: tituloRecord,
          tipo: datosTratamientoRancho.tipo,
          resultado: datosTratamientoRancho.resultado,
          modoAplicacion: "masivo_potreros",
          completada: false,
          origen: "planeado",
          ranchoId: usuario?.ranchoId || null
        });
      }

      setExitoTratRancho(`✅ Tratamiento registrado en ${potrerosAfectados.length} potreros.`);
      setCrearRecordatorio(false);
      setFechaRecordatorio("");
      setTimeout(() => { setExitoTratRancho(""); setModalTratamientoRancho(false); }, 2000);
    } catch (err) { console.error(err); }
    setGuardandoTratRancho(false);
  };

  // ─── Grupos ───────────────────────────────────────────────────────────────────

  const guardarGrupo = async (e) => {
    e.preventDefault();
    try {
      const grupoData = { 
        nombre: datosFormGrupo.nombre,
        ranchoId: usuario?.ranchoId || null
      };
      if (editandoGrupoId) {
        await updateDoc(doc(db, "grupos", editandoGrupoId), grupoData);
      } else {
        await addDoc(collection(db, "grupos"), grupoData);
      }
      setFormGrupoActivo(false);
      setEditandoGrupoId(null);
      setDatosFormGrupo({ nombre: "" });
    } catch (error) { console.error("Error guardando grupo:", error); }
  };

  const editarGrupo = (g) => {
    setDatosFormGrupo({ nombre: g.nombre });
    setEditandoGrupoId(g.id);
    setFormGrupoActivo(true);
  };

  const borrarGrupo = async (id) => {
    if (window.confirm("¿Seguro que deseas eliminar este grupo de manejo?")) {
      try { await deleteDoc(doc(db, "grupos", id)); }
      catch (error) { console.error("Error borrando grupo:", error); }
    }
  };

  // ─── Traslado Masivo ────────────────────────────────────────────────────────
  const abrirModalTraslado = (tipo, nombreOrigen) => {
    setDatosTraslado({ tipo, nombreOrigen, potreroDestino: "", grupoDestino: "" });
    setExitoTraslado("");
    setModalTraslado(true);
  };

  const ejecutarTrasladoMasivo = async (e) => {
    e.preventDefault();
    setGuardandoTraslado(true);
    try {
      const q = query(collection(db, "animales"), where("ranchoId", "==", usuario?.ranchoId));
      const snap = await getDocs(q);
      
      const docsFiltrados = snap.docs.filter(doc => {
        const campo = datosTraslado.tipo === "potrero" ? "potrero" : "grupo";
        return doc.data()[campo] === datosTraslado.nombreOrigen;
      });

      let count = 0;
      
      for (const animalDoc of docsFiltrados) {
        const updateData = {};
        if (datosTraslado.potreroDestino) updateData.potrero = datosTraslado.potreroDestino === "Sin Asignar" ? "" : datosTraslado.potreroDestino;
        if (datosTraslado.grupoDestino) updateData.grupo = datosTraslado.grupoDestino === "Sin Asignar" ? "" : datosTraslado.grupoDestino;
        
        if (Object.keys(updateData).length > 0) {
          await updateDoc(doc(db, "animales", animalDoc.id), updateData);
          count++;
        }
      }
      
      setExitoTraslado(`✅ Se trasladaron ${count} animales exitosamente.`);
      setTimeout(() => { setExitoTraslado(""); setModalTraslado(false); }, 2000);
    } catch (error) {
      console.error("Error en traslado masivo:", error);
    }
    setGuardandoTraslado(false);
  };

  const getTotalHectareas = () => potreros.reduce((total, p) => total + (p.hectareas || 0), 0);

  // ─── UI ──────────────────────────────────────────────────────────────────────

  return (
    <div className="dashboard-container">
      <div className="page-header" style={{ marginBottom: "20px", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap" }}>
        <div>
          <h1 style={{ display: "flex", alignItems: "center", gap: "16px" }}>
            <img src={require("../assets/logo_potreros.jpg")} alt="Potreros" style={{ width: "64px", height: "64px", objectFit: "contain", borderRadius: "12px", border: "1px solid #e5e7eb", backgroundColor: "white" }} />
            Mi Rancho
          </h1>
          <p>Administra los Potreros, Divisiones Internas y Grupos de Manejo de tu rancho.</p>
        </div>
        <button 
          className="btn-primary" 
          onClick={() => {
            setDatosTratamientoRancho({ potreroId: "Todos", tipo: "Herbicida", resultado: "", fecha: new Date().toISOString().split("T")[0] });
            setExitoTratRancho("");
            setModalTratamientoRancho(true);
          }}
          style={{ margin: 0, width: "auto", display: "flex", alignItems: "center", gap: "6px", backgroundColor: "#16a34a", borderColor: "#16a34a", padding: "10px 20px" }}
        >
          💊 Cargar Tratamiento
        </button>
      </div>

      {/* 📊 PERFIL OPERATIVO (Benchmark) */}
      <div className="card" style={{ padding: "20px", marginBottom: "20px", borderLeft: "4px solid #3b82f6" }}>
        <h2 style={{ margin: "0 0 10px 0", fontSize: "18px", color: "#1e40af" }}>Perfil Operativo y Benchmark</h2>
        <p style={{ fontSize: "13px", color: "var(--gris-400)", marginBottom: "15px" }}>Configura estos datos para poder comparar el rendimiento de tu rancho (Benchmark) contra ranchos similares de tu región. Todos los datos de comparación son 100% anónimos.</p>
        
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
          <div>
            <label style={labelStyle}>Vocación Principal del Rancho</label>
            <select 
              value={ranchoDoc?.vocacion || ""} 
              onChange={(e) => guardarPerfilRancho("vocacion", e.target.value)}
              style={inputStyle}
              disabled={guardandoPerfil || usuario?.rol !== "admin"}
            >
              <option value="">-- Selecciona Vocación --</option>
              <option value="Leche">Establo Lechero (Leche)</option>
              <option value="Cría">Pie de Cría (Venta de Becerros)</option>
              <option value="Engorda">Feedlot / Engorda (Carne)</option>
              <option value="Doble Propósito">Doble Propósito (Leche y Cría)</option>
            </select>
          </div>
          <div>
            <label style={labelStyle}>Estado / Región</label>
            <select 
              value={ranchoDoc?.estadoRegion || ""} 
              onChange={(e) => guardarPerfilRancho("estadoRegion", e.target.value)}
              style={inputStyle}
              disabled={guardandoPerfil || usuario?.rol !== "admin"}
            >
              <option value="">-- Selecciona Estado --</option>
              <option value="Aguascalientes">Aguascalientes</option>
              <option value="Baja California">Baja California</option>
              <option value="Baja California Sur">Baja California Sur</option>
              <option value="Campeche">Campeche</option>
              <option value="Chiapas">Chiapas</option>
              <option value="Chihuahua">Chihuahua</option>
              <option value="Coahuila">Coahuila</option>
              <option value="Colima">Colima</option>
              <option value="Ciudad de México">Ciudad de México</option>
              <option value="Durango">Durango</option>
              <option value="Guanajuato">Guanajuato</option>
              <option value="Guerrero">Guerrero</option>
              <option value="Hidalgo">Hidalgo</option>
              <option value="Jalisco">Jalisco</option>
              <option value="Estado de México">Estado de México</option>
              <option value="Michoacán">Michoacán</option>
              <option value="Morelos">Morelos</option>
              <option value="Nayarit">Nayarit</option>
              <option value="Nuevo León">Nuevo León</option>
              <option value="Oaxaca">Oaxaca</option>
              <option value="Puebla">Puebla</option>
              <option value="Querétaro">Querétaro</option>
              <option value="Quintana Roo">Quintana Roo</option>
              <option value="San Luis Potosí">San Luis Potosí</option>
              <option value="Sinaloa">Sinaloa</option>
              <option value="Sonora">Sonora</option>
              <option value="Tabasco">Tabasco</option>
              <option value="Tamaulipas">Tamaulipas</option>
              <option value="Tlaxcala">Tlaxcala</option>
              <option value="Veracruz">Veracruz</option>
              <option value="Yucatán">Yucatán</option>
              <option value="Zacatecas">Zacatecas</option>
              <option value="Otro País">Otro País</option>
            </select>
          </div>
        </div>
      </div>

      {/* ══ UPPs (Unidades de Producción Pecuaria) ══════════════════════════════════════════════════ */}
      <div className="card" style={{ padding: "20px", marginBottom: "20px" }}>
        <h2 style={{ margin: "0 0 10px 0", fontSize: "18px" }}>Mis UPPs (Unidades de Producción Pecuaria)</h2>
        <p style={{ fontSize: "13px", color: "var(--gris-400)", marginBottom: "15px" }}>Identificadores oficiales de tu rancho. Requeridos para guías de tránsito y movilización.</p>
        
        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap", marginBottom: "15px" }}>
          {(ranchoDoc?.upps || []).map((upp, idx) => (
            <div key={idx} style={{ backgroundColor: "#f3f4f6", padding: "8px 12px", borderRadius: "6px", display: "flex", alignItems: "center", gap: "10px", border: "1px solid #e5e7eb" }}>
              <span style={{ fontWeight: "bold", color: "#374151" }}>{upp}</span>
              {usuario?.rol === "admin" && (
                <button onClick={() => quitarUpp(idx)} style={{ background: "none", border: "none", color: "#ef4444", cursor: "pointer", padding: 0, display: "flex" }} title="Eliminar UPP"><X size={16} /></button>
              )}
            </div>
          ))}
          {(!ranchoDoc?.upps || ranchoDoc.upps.length === 0) && (
            <div style={{ color: "#9ca3af", fontSize: "13px", fontStyle: "italic" }}>No has registrado ninguna UPP todavía.</div>
          )}
        </div>

        {usuario?.rol === "admin" && (
          <div style={{ display: "flex", gap: "10px", alignItems: "center", flexWrap: "wrap" }}>
            <input type="text" placeholder="Ej: 30 189 1447 002" value={nuevaUpp} onChange={e => setNuevaUpp(e.target.value)} style={{...inputStyle, flex: 1, minWidth: "150px", margin: 0}} />
            <button onClick={agregarUpp} className="btn-primary" style={{ margin: 0, width: "auto" }} disabled={guardandoUpp || !nuevaUpp.trim()}>
              {guardandoUpp ? "Guardando..." : "Añadir UPP"}
            </button>
          </div>
        )}
      </div>

      {/* ══ TABLA DE POTREROS ══════════════════════════════════════════════════ */}
      <div className="card" style={{ padding: "20px", marginBottom: "20px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
          <div>
            <h2 style={{ margin: 0, fontSize: "18px" }}>Mis Potreros</h2>
            <div style={{ fontSize: "13px", color: "var(--gris-400)", marginTop: "4px" }}>
              Total de superficie: <strong style={{ color: "var(--verde-oscuro)" }}>{getTotalHectareas()} Has</strong>
            </div>
          </div>
          {!formActivo && (
            <button className="btn-primary" style={{ width: "auto", padding: "8px 16px" }} onClick={() => { setFormActivo(true); setEditandoId(null); }}>
              <Plus size={18} /> Nuevo Potrero
            </button>
          )}
        </div>

        {/* Formulario Potrero */}
        {formActivo && (
          <form onSubmit={guardarPotrero} style={{ backgroundColor: "#f9fafb", padding: "15px", borderRadius: "8px", border: "1px solid #e5e7eb", marginBottom: "20px" }}>
            <h3 style={{ fontSize: "15px", marginTop: 0, marginBottom: "15px", color: "#374151" }}>
              {editandoId ? "Editar Potrero" : "Crear Nuevo Potrero"}
            </h3>

            <div style={{ display: "flex", gap: "10px", flexWrap: "wrap", marginBottom: "12px" }}>
              {/* Nombre */}
              <div style={{ flex: "1 1 200px" }}>
                <label style={labelStyle}>Nombre del Potrero</label>
                <input type="text" placeholder="Ej: Potrero Norte, Lote 4..."
                  value={datosForm.nombre} onChange={e => setDatosForm({...datosForm, nombre: e.target.value})}
                  required style={inputStyle} />
              </div>
              {/* Hectáreas */}
              <div style={{ flex: "1 1 140px" }}>
                <label style={labelStyle}>Extensión (Hectáreas)</label>
                <input type="number" step="0.01" placeholder="Ej: 50.5"
                  value={datosForm.hectareas} onChange={e => setDatosForm({...datosForm, hectareas: e.target.value})}
                  required style={inputStyle} />
              </div>
              {/* Tipo de Pasto */}
              <div style={{ flex: "1 1 200px" }}>
                <label style={labelStyle}>Tipo de Pasto (Nombre)</label>
                <input type="text" placeholder="Ej: Bermudas, Pangola..."
                  value={datosForm.tipoPastoNombre} onChange={e => setDatosForm({...datosForm, tipoPastoNombre: e.target.value})}
                  style={inputStyle} />
              </div>
              {/* % Maleza */}
              <div style={{ flex: "1 1 100px" }}>
                <label style={labelStyle}>% Maleza</label>
                <input type="number" min="1" max="100" placeholder="Ej: 20"
                  value={datosForm.porcentajePasto} onChange={e => setDatosForm({...datosForm, porcentajePasto: e.target.value})}
                  style={inputStyle} />
              </div>
              {/* Tamaño con ejemplos */}
              <div style={{ flex: "1 1 200px" }}>
                <label style={labelStyle}>Tamaño del Pasto</label>
                <select value={datosForm.tipoPastoTamano}
                  onChange={e => setDatosForm({...datosForm, tipoPastoTamano: e.target.value})}
                  style={inputStyle}>
                  <option value="">-- Seleccionar --</option>
                  <option value="Corto">Corto (bermudas, pangola)</option>
                  <option value="Mediano">Mediano (estrella, brizanta)</option>
                  <option value="Alto">Alto (mombasa, Tanzania)</option>
                  <option value="Corte">Corte (Taiwán, maíz, caña de azúcar)</option>
                </select>
              </div>
              {/* Número de Presas */}
              <div style={{ flex: "1 1 120px" }}>
                <label style={labelStyle}>Núm. de Presas</label>
                <input type="number" min="0" placeholder="Ej: 2"
                  value={datosForm.numeroPresas} onChange={e => setDatosForm({...datosForm, numeroPresas: e.target.value})}
                  style={inputStyle} />
              </div>
              {/* Número de Bebederos */}
              <div style={{ flex: "1 1 120px" }}>
                <label style={labelStyle}>Núm. Bebederos</label>
                <input type="number" min="0" placeholder="Ej: 4"
                  value={datosForm.numeroBebederos} onChange={e => setDatosForm({...datosForm, numeroBebederos: e.target.value})}
                  style={inputStyle} />
              </div>
            </div>

            {/* Divisiones Internas */}
            <div style={{ marginBottom: "15px" }}>
              <label style={labelStyle}>Divisiones Internas</label>
              <div style={{ display: "flex", gap: "8px", marginBottom: "8px" }}>
                <input
                  type="text"
                  placeholder="Ej: Norte, Bloque A, Sector 1..."
                  value={nuevaDivision}
                  onChange={e => setNuevaDivision(e.target.value)}
                  onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); agregarDivision(); } }}
                  style={{ ...inputStyle, flex: 1 }}
                />
                <button type="button" onClick={agregarDivision}
                  style={{ padding: "8px 14px", backgroundColor: "#3b82f6", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", fontWeight: "600", whiteSpace: "nowrap" }}>
                  + Agregar
                </button>
              </div>
              {datosForm.divisiones.length > 0 && (
                <div style={{ display: "flex", flexWrap: "wrap", gap: "6px" }}>
                  {datosForm.divisiones.map((div, i) => (
                    <span key={i} style={{ backgroundColor: "#dbeafe", color: "#1e40af", padding: "4px 10px", borderRadius: "20px", fontSize: "12px", display: "flex", alignItems: "center", gap: "5px" }}>
                      {div}
                      <button type="button" onClick={() => quitarDivision(i)}
                        style={{ background: "none", border: "none", cursor: "pointer", color: "#1e40af", padding: 0, lineHeight: 1, fontSize: "14px" }}>×</button>
                    </span>
                  ))}
                </div>
              )}
            </div>

            <div style={{ display: "flex", gap: "10px" }}>
              <button type="submit" className="btn-primary" style={{ margin: 0 }}>Guardar Potrero</button>
              <button type="button" className="btn-outline" style={{ margin: 0 }} onClick={cerrarFormPotrero}>Cancelar</button>
            </div>
          </form>
        )}

        {/* Tabla */}
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "13px", textAlign: "left" }}>
            <thead>
              <tr style={{ borderBottom: "2px solid #e5e7eb", color: "#6b7280", backgroundColor: "#f9fafb" }}>
                <th style={{ padding: "10px 8px" }}>Potrero</th>
                <th style={{ padding: "10px 8px" }}>Hectáreas</th>
                <th style={{ padding: "10px 8px" }}>Pasto</th>
                <th style={{ padding: "10px 8px" }}>% Maleza</th>
                <th style={{ padding: "10px 8px" }}>Tamaño</th>
                <th style={{ padding: "10px 8px" }}>Presas</th>
                <th style={{ padding: "10px 8px" }}>Bebederos</th>
                <th style={{ padding: "10px 8px" }}>Divisiones</th>
                <th style={{ padding: "10px 8px", textAlign: "center" }}>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {potreros.length === 0 ? (
                <tr><td colSpan="7" style={{ padding: "20px", textAlign: "center", color: "#9ca3af" }}>No hay potreros registrados.</td></tr>
              ) : (
                potreros.map(pot => (
                  <tr key={pot.id} style={{ borderBottom: "1px solid #f3f4f6" }}>
                    <td style={{ padding: "10px 8px", fontWeight: "600", color: "#111827" }}>{pot.nombre}</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>{pot.hectareas} ha</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>{pot.tipoPastoNombre || "-"}</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>{pot.porcentajePasto ? `${pot.porcentajePasto}%` : "-"}</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>{pot.tipoPastoTamano || "-"}</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>{pot.numeroPresas || "0"}</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>{pot.numeroBebederos || "0"}</td>
                    <td style={{ padding: "10px 8px", color: "#4b5563" }}>
                      {pot.divisiones?.length > 0
                        ? <span title={pot.divisiones.join(", ")}>{pot.divisiones.length} div. ({pot.divisiones.slice(0,2).join(", ")}{pot.divisiones.length > 2 ? "..." : ""})</span>
                        : "-"}
                    </td>
                    <td style={{ padding: "10px 8px", textAlign: "center" }}>
                      <div style={{ display: "flex", justifyContent: "center", gap: "6px" }}>
                        <button onClick={() => abrirModalTratamiento(pot)}
                          title="Cargar Tratamiento"
                          style={{ background: "#dcfce7", border: "1px solid #86efac", borderRadius: "6px", cursor: "pointer", color: "#166534", padding: "4px 8px", fontSize: "11px", fontWeight: "600", display: "flex", alignItems: "center", gap: "3px" }}>
                          💊 Trat.
                        </button>
                        <button onClick={() => abrirModalTraslado("potrero", pot.nombre)}
                          title="Trasladar Ganado"
                          style={{ background: "#dbeafe", border: "1px solid #93c5fd", borderRadius: "6px", cursor: "pointer", color: "#1e40af", padding: "4px 8px", fontSize: "11px", fontWeight: "600", display: "flex", alignItems: "center", gap: "3px" }}>
                          🚜 Mover
                        </button>
                        <button onClick={() => abrirHistorial(pot)}
                          title="Ver historial"
                          style={{ background: "none", border: "none", cursor: "pointer", color: "#6b7280" }}>
                          <ClipboardList size={16} />
                        </button>
                        <button onClick={() => editarPotrero(pot)}
                          style={{ background: "none", border: "none", cursor: "pointer", color: "#3b82f6" }} title="Editar">
                          <Edit2 size={16} />
                        </button>
                        <button onClick={() => borrarPotrero(pot.id)}
                          style={{ background: "none", border: "none", cursor: "pointer", color: "#ef4444" }} title="Eliminar">
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* ══ GRUPOS DE MANEJO ══════════════════════════════════════════════════ */}
      <div className="card" style={{ padding: "20px", marginBottom: "20px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
          <div>
            <h2 style={{ margin: 0, fontSize: "18px" }}>Grupos de Manejo</h2>
            <div style={{ fontSize: "13px", color: "var(--gris-400)", marginTop: "4px" }}>
              Categoriza el ganado para aplicar tratamientos masivos rápido.
            </div>
          </div>
          {!formGrupoActivo && (
            <button className="btn-primary" style={{ width: "auto", padding: "8px 16px" }} onClick={() => { setFormGrupoActivo(true); setEditandoGrupoId(null); setDatosFormGrupo({ nombre: "" }); }}>
              <Plus size={18} /> Nuevo Grupo
            </button>
          )}
        </div>

        {formGrupoActivo && (
          <form onSubmit={guardarGrupo} style={{ backgroundColor: "#f9fafb", padding: "15px", borderRadius: "8px", border: "1px solid #e5e7eb", marginBottom: "20px" }}>
            <h3 style={{ fontSize: "15px", marginTop: 0, marginBottom: "15px", color: "#374151" }}>
              {editandoGrupoId ? "Editar Grupo" : "Crear Nuevo Grupo"}
            </h3>
            <div style={{ display: "flex", gap: "10px", flexWrap: "wrap", marginBottom: "15px" }}>
              <div style={{ flex: "1 1 200px" }}>
                <label style={labelStyle}>Nombre del Grupo / Lote</label>
                <input type="text" placeholder="Ej: Crías Lactantes, Vacas Secas..."
                  value={datosFormGrupo.nombre} onChange={e => setDatosFormGrupo({ nombre: e.target.value })}
                  required style={inputStyle} />
              </div>
            </div>
            <div style={{ display: "flex", gap: "10px" }}>
              <button type="submit" className="btn-primary" style={{ margin: 0 }}>Guardar Grupo</button>
              <button type="button" className="btn-outline" style={{ margin: 0 }} onClick={() => { setFormGrupoActivo(false); setEditandoGrupoId(null); }}>Cancelar</button>
            </div>
          </form>
        )}

        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "14px", textAlign: "left" }}>
            <thead>
              <tr style={{ borderBottom: "2px solid #e5e7eb", color: "#6b7280" }}>
                <th style={{ padding: "12px 8px" }}>Nombre del Grupo</th>
                <th style={{ padding: "12px 8px", width: "100px", textAlign: "center" }}>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {grupos.length === 0 ? (
                <tr><td colSpan="2" style={{ padding: "20px", textAlign: "center", color: "#9ca3af" }}>No hay grupos registrados.</td></tr>
              ) : (
                grupos.map(g => (
                  <tr key={g.id} style={{ borderBottom: "1px solid #f3f4f6" }}>
                    <td style={{ padding: "12px 8px", fontWeight: "500", color: "#111827" }}>{g.nombre}</td>
                    <td style={{ padding: "12px 8px", textAlign: "center", display: "flex", justifyContent: "center", gap: "8px" }}>
                      <button onClick={() => abrirModalTraslado("grupo", g.nombre)}
                        title="Trasladar Ganado"
                        style={{ background: "#dbeafe", border: "1px solid #93c5fd", borderRadius: "6px", cursor: "pointer", color: "#1e40af", padding: "4px 8px", fontSize: "11px", fontWeight: "600", display: "flex", alignItems: "center", gap: "3px" }}>
                        🚜 Mover
                      </button>
                      <button onClick={() => editarGrupo(g)} style={{ background: "none", border: "none", cursor: "pointer", color: "#3b82f6" }} title="Editar"><Edit2 size={18} /></button>
                      <button onClick={() => borrarGrupo(g.id)} style={{ background: "none", border: "none", cursor: "pointer", color: "#ef4444" }} title="Eliminar"><Trash2 size={18} /></button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Nota */}
      <div className="card" style={{ padding: "20px", backgroundColor: "#fefce8", border: "1px solid #fef08a" }}>
        <h3 style={{ margin: "0 0 10px 0", color: "#854d0e", display: "flex", alignItems: "center", gap: "6px" }}>
          <ShieldAlert size={20} /> Nota sobre Asignaciones
        </h3>
        <p style={{ margin: 0, fontSize: "13px", color: "#713f12", lineHeight: "1.5" }}>
          Al borrar un Potrero, los animales que estaban asignados figurarán como "Sin Asignar". Los tratamientos registrados en el potrero se conservan en el historial.
        </p>
      </div>

      {/* ══ MODAL TRATAMIENTO POTRERO ══════════════════════════════════════════ */}
      {modalTratamiento && potreroActivo && (
        <div className="modal-overlay" onClick={() => setModalTratamiento(false)}>
          <div className="modal-content" style={{ maxWidth: "480px" }} onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h2 style={{ margin: 0, fontSize: "18px", color: "#111827" }}>💊 Cargar Tratamiento</h2>
                <p style={{ margin: "4px 0 0", color: "#6b7280", fontSize: "13px" }}>Potrero: <strong>{potreroActivo.nombre}</strong></p>
              </div>
              <button onClick={() => setModalTratamiento(false)} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={22} color="#9ca3af" />
              </button>
            </div>

            {exitoTrat && (
              <div className="file-status status-success" style={{ marginBottom: "14px" }}><span>{exitoTrat}</span></div>
            )}

            <form onSubmit={guardarTratamientoPotrero}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px", marginBottom: "14px" }}>
                <div>
                  <label style={labelStyle}>Tipo de Actividad</label>
                  <select value={datosTratamiento.tipo}
                    onChange={e => setDatosTratamiento({ ...datosTratamiento, tipo: e.target.value, resultado: "" })}
                    style={{ ...inputStyle, padding: "10px 12px" }}>
                    {TIPOS_EVENTO_POTRERO.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label style={labelStyle}>Fecha</label>
                  <input type="date" value={datosTratamiento.fecha}
                    onChange={e => setDatosTratamiento({ ...datosTratamiento, fecha: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px" }} required />
                </div>
              </div>

              {CATALOGO_EVENTOS_POTRERO[datosTratamiento.tipo]?.length > 0 ? (
                <div style={{ marginBottom: "14px" }}>
                  <label style={labelStyle}>Insumo / Tipo Específico</label>
                  <select value={datosTratamiento.resultado}
                    onChange={e => setDatosTratamiento({ ...datosTratamiento, resultado: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px", border: "1px solid #3b82f6", backgroundColor: "#eff6ff" }} required>
                    <option value="">-- Selecciona --</option>
                    {CATALOGO_EVENTOS_POTRERO[datosTratamiento.tipo].map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              ) : (
                <div style={{ marginBottom: "14px" }}>
                  <label style={labelStyle}>Detalle / Resultado</label>
                  <input type="text" placeholder="Ej: Observación, producto usado..."
                    value={datosTratamiento.resultado}
                    onChange={e => setDatosTratamiento({ ...datosTratamiento, resultado: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px" }} required />
                </div>
              )}

              <button type="submit" className="btn-primary" style={{ width: "100%", marginTop: 0 }} disabled={guardandoTrat}>
                {guardandoTrat ? "Guardando..." : "Registrar Tratamiento"}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* ══ MODAL HISTORIAL POTRERO ════════════════════════════════════════════ */}
      {modalHistorial && potreroActivo && (
        <div className="modal-overlay" onClick={() => setModalHistorial(false)}>
          <div className="modal-content" style={{ maxWidth: "520px" }} onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h2 style={{ margin: 0, fontSize: "18px" }}>Historial: {potreroActivo.nombre}</h2>
                <p style={{ margin: "4px 0 0", color: "#6b7280", fontSize: "13px" }}>Tratamientos y actividades registradas</p>
              </div>
              <button onClick={() => setModalHistorial(false)} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={22} color="#9ca3af" />
              </button>
            </div>

            {cargandoHistorial ? (
              <p style={{ textAlign: "center", color: "#9ca3af" }}>Cargando...</p>
            ) : historialPotrero.length === 0 ? (
              <p style={{ textAlign: "center", color: "#9ca3af", padding: "20px 0" }}>No hay tratamientos registrados para este potrero.</p>
            ) : (
              <div style={{ maxHeight: "380px", overflowY: "auto" }}>
                {historialPotrero.map(ev => (
                  <div key={ev.id} style={{ padding: "10px 0", borderBottom: "1px solid #f3f4f6", display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div>
                      <span style={{ fontWeight: "600", color: "#111827", fontSize: "14px" }}>{ev.tipo}</span>
                      {ev.resultado && <span style={{ color: "#6b7280", fontSize: "13px" }}> — {ev.resultado}</span>}
                      {ev.costo > 0 && <span style={{ color: "#ef4444", fontSize: "12px", marginLeft: "8px" }}>(${ev.costo})</span>}
                    </div>
                    <span style={{ color: "#9ca3af", fontSize: "12px", whiteSpace: "nowrap", marginLeft: "12px" }}>{ev.fecha}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* ══ MODAL TRASLADO MASIVO ══════════════════════════════════════════════ */}
      {modalTraslado && (
        <div className="modal-overlay" onClick={() => !guardandoTraslado && setModalTraslado(false)}>
          <div className="modal-content" style={{ maxWidth: "400px" }} onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h2 style={{ margin: 0, fontSize: "18px", color: "#111827" }}>🚜 Traslado Masivo</h2>
                <p style={{ margin: "4px 0 0", color: "#6b7280", fontSize: "13px" }}>
                  Mover animales de {datosTraslado.tipo === "potrero" ? "potrero" : "grupo"} <strong>{datosTraslado.nombreOrigen}</strong>
                </p>
              </div>
              <button onClick={() => !guardandoTraslado && setModalTraslado(false)} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={22} color="#9ca3af" />
              </button>
            </div>

            {exitoTraslado && (
              <div className="file-status status-success" style={{ marginBottom: "14px" }}><span>{exitoTraslado}</span></div>
            )}

            <form onSubmit={ejecutarTrasladoMasivo}>
              {datosTraslado.tipo === "potrero" && (
                <div style={{ marginBottom: "20px" }}>
                  <label style={labelStyle}>Nuevo Potrero de Destino</label>
                  <select value={datosTraslado.potreroDestino}
                    onChange={e => setDatosTraslado({ ...datosTraslado, potreroDestino: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px" }}>
                    <option value="">Seleccionar potrero...</option>
                    <option value="Sin Asignar">Sin Asignar (Quitar potrero)</option>
                    {potreros.filter(p => p.nombre !== datosTraslado.nombreOrigen).map(p => <option key={p.id} value={p.nombre}>{p.nombre}</option>)}
                  </select>
                </div>
              )}

              {datosTraslado.tipo === "grupo" && (
                <div style={{ marginBottom: "20px" }}>
                  <label style={labelStyle}>Nuevo Grupo de Destino</label>
                  <select value={datosTraslado.grupoDestino}
                    onChange={e => setDatosTraslado({ ...datosTraslado, grupoDestino: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px" }}>
                    <option value="">Seleccionar grupo...</option>
                    <option value="Sin Asignar">Sin Asignar (Quitar grupo)</option>
                    {grupos.filter(g => g.nombre !== datosTraslado.nombreOrigen).map(g => <option key={g.id} value={g.nombre}>{g.nombre}</option>)}
                  </select>
                </div>
              )}

              <button type="submit" className="btn-primary" style={{ width: "100%", marginTop: 0 }} disabled={guardandoTraslado || (!datosTraslado.potreroDestino && !datosTraslado.grupoDestino)}>
                {guardandoTraslado ? "Moviendo..." : "Confirmar Traslado"}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* ══ MODAL TRATAMIENTO MASIVO (RANCHO) ══════════════════════════════════════════ */}
      {modalTratamientoRancho && (
        <div className="modal-overlay" onClick={() => setModalTratamientoRancho(false)}>
          <div className="modal-content" style={{ maxWidth: "480px" }} onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h2 style={{ margin: 0, fontSize: "18px", color: "#111827" }}>Registrar evento en potrero</h2>
                <p style={{ margin: "4px 0 0", color: "#6b7280", fontSize: "13px" }}>Aplica insumos directamente al suelo o pasto.</p>
              </div>
              <button onClick={() => setModalTratamientoRancho(false)} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={22} color="#9ca3af" />
              </button>
            </div>

            {exitoTratRancho && (
              <div className="file-status status-success" style={{ marginBottom: "14px" }}><span>{exitoTratRancho}</span></div>
            )}

            <form onSubmit={guardarTratamientoRancho}>
              <div style={{ marginBottom: "14px" }}>
                <label style={labelStyle}>Seleccionar Potrero(s)</label>
                <select value={datosTratamientoRancho.potreroId}
                  onChange={e => setDatosTratamientoRancho({ ...datosTratamientoRancho, potreroId: e.target.value })}
                  style={{ ...inputStyle, padding: "10px 12px" }}>
                  <option value="Todos">Todos los Potreros</option>
                  {potreros.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
                </select>
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px", marginBottom: "14px" }}>
                <div>
                  <label style={labelStyle}>Tipo de Actividad</label>
                  <select value={datosTratamientoRancho.tipo}
                    onChange={e => setDatosTratamientoRancho({ ...datosTratamientoRancho, tipo: e.target.value, resultado: "" })}
                    style={{ ...inputStyle, padding: "10px 12px" }}>
                    {TIPOS_EVENTO_POTRERO.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label style={labelStyle}>Fecha</label>
                  <input type="date" value={datosTratamientoRancho.fecha}
                    onChange={e => setDatosTratamientoRancho({ ...datosTratamientoRancho, fecha: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px" }} required />
                </div>
              </div>

              {CATALOGO_EVENTOS_POTRERO[datosTratamientoRancho.tipo]?.length > 0 ? (
                <div style={{ marginBottom: "14px" }}>
                  <label style={labelStyle}>Insumo / Tipo Específico</label>
                  <select value={datosTratamientoRancho.resultado}
                    onChange={e => setDatosTratamientoRancho({ ...datosTratamientoRancho, resultado: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px", border: "1px solid #3b82f6", backgroundColor: "#eff6ff" }} required>
                    <option value="">-- Selecciona --</option>
                    {CATALOGO_EVENTOS_POTRERO[datosTratamientoRancho.tipo].map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              ) : (
                <div style={{ marginBottom: "14px" }}>
                  <label style={labelStyle}>Detalle / Resultado</label>
                  <input type="text" placeholder="Ej: Observación, producto usado..."
                    value={datosTratamientoRancho.resultado}
                    onChange={e => setDatosTratamientoRancho({ ...datosTratamientoRancho, resultado: e.target.value })}
                    style={{ ...inputStyle, padding: "10px 12px" }} required />
                </div>
              )}

              <div style={{ marginBottom: "15px", padding: "10px", backgroundColor: "#f0fdf4", borderRadius: "8px", border: "1px solid #bbf7d0" }}>
                <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontWeight: "600", fontSize: "13px", color: "#166534" }}>
                  <input
                    type="checkbox"
                    checked={crearRecordatorio}
                    onChange={e => setCrearRecordatorio(e.target.checked)}
                    style={{ width: "16px", height: "16px", accentColor: "#16a34a" }}
                  />
                  📅 Programar recordatorio en el Calendario
                </label>
                {crearRecordatorio && (
                  <div style={{ marginTop: "10px" }}>
                    <label style={{ display: "block", fontSize: "12px", fontWeight: "600", marginBottom: "4px", color: "#14532d" }}>Fecha del Recordatorio</label>
                    <div style={{ display: "flex", gap: "8px", alignItems: "center", flexWrap: "wrap" }}>
                      <input
                        type="date"
                        value={fechaRecordatorio}
                        onChange={e => setFechaRecordatorio(e.target.value)}
                        style={{ flex: 1, padding: "8px", border: "1px solid #22c55e", borderRadius: "6px" }}
                      />
                      <button type="button" onClick={() => {
                        const d = new Date(datosTratamientoRancho.fecha + "T00:00:00");
                        d.setDate(d.getDate() - 1);
                        setFechaRecordatorio(d.toISOString().split("T")[0]);
                      }} style={{ fontSize: "11px", padding: "6px 10px", border: "1px solid #22c55e", borderRadius: "6px", backgroundColor: "#dcfce7", color: "#15803d", cursor: "pointer", whiteSpace: "nowrap" }}>
                        1 día antes
                      </button>
                    </div>
                  </div>
                )}
              </div>

              <button type="submit" className="btn-primary" style={{ width: "100%", marginTop: 0 }} disabled={guardandoTratRancho}>
                {guardandoTratRancho ? "Guardando..." : "Registrar Evento"}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
